"""Histórico da área de transferência (Mac e Windows): guarda os textos copiados para colar de novo depois.

Senhas copiadas de gerenciadores de senha (1Password, Bitwarden, Chaves do iCloud...) são ignoradas:
esses apps marcam a cópia como secreta e o Treco respeita.
"""
import json
import os
import threading
import time

from ..core.paths import WINDOWS, data_dir

LIMIT = 200
SECRET_TYPES = {"org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
                "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword",
                "de.petermaurer.TransientPasteboardType"}


def _file():
    return os.path.join(data_dir(), "historico de copias.json")


class History:
    def __init__(self, path=None):
        self.path = path or _file()
        self.lock = threading.Lock()
        self.items = self._load()
        self.count = None

    def _load(self):
        try:
            with open(self.path, encoding="utf-8") as f:
                items = json.load(f)
            return [i for i in items if isinstance(i, dict) and isinstance(i.get("text"), str)][:LIMIT]
        except (OSError, ValueError):
            return []

    def save(self):
        try:
            os.makedirs(os.path.dirname(self.path), exist_ok=True)
            temp = self.path + ".tmp"
            with open(temp, "w", encoding="utf-8") as f:
                json.dump(self.items, f, ensure_ascii=False)
            os.chmod(temp, 0o600)  # só a sua conta do Mac lê
            os.replace(temp, self.path)
        except OSError:
            pass

    def add(self, text):
        if not text or not text.strip() or len(text) > 100_000:
            return False
        with self.lock:
            self.items = [i for i in self.items if i["text"] != text]  # repetido sobe para o topo
            self.items.insert(0, {"text": text, "at": time.time()})
            del self.items[LIMIT:]
            self.save()
        return True

    def remove(self, text):
        with self.lock:
            self.items = [i for i in self.items if i["text"] != text]
            self.save()

    def clear(self):
        with self.lock:
            self.items = []
            self.save()

    def search(self, words):
        words = words.strip().lower()
        return [i for i in self.items if words in i["text"].lower()] if words else list(self.items)


def pasteboard_change():
    """(número da mudança, texto ou None). Texto None quando não é texto ou quando é secreto."""
    if WINDOWS:
        from .win_utils import pasteboard_change as windows_change
        return windows_change()
    from AppKit import NSPasteboard, NSPasteboardTypeString
    board = NSPasteboard.generalPasteboard()
    count = board.changeCount()
    types = {str(t) for t in (board.types() or [])}
    if types & SECRET_TYPES:
        return count, None
    text = board.stringForType_(NSPasteboardTypeString)
    return count, (str(text) if text is not None else None)


class Watcher:
    """Olha a área de transferência a cada segundo, sem atrapalhar nada."""

    def __init__(self, root, history=None, enabled=lambda: True):
        self.root, self.history, self.enabled = root, history or History(), enabled
        self.last = None
        self.alive = True

    def start(self):
        try:
            self.last, _ = pasteboard_change()  # o que já estava copiado antes de abrir o Treco não entra
        except Exception:
            return
        self.root.after(1000, self.tick)

    def tick(self):
        if not self.alive:
            return
        try:
            count, text = pasteboard_change()
            if count != self.last:
                self.last = count
                if text and self.enabled():
                    self.history.add(text)
        except Exception:
            pass
        self.root.after(1000, self.tick)


def when(seconds_ago):
    if seconds_ago < 60:
        return "agora"
    if seconds_ago < 3600:
        return f"{int(seconds_ago // 60)} min"
    if seconds_ago < 86400:
        return f"{int(seconds_ago // 3600)} h"
    days = int(seconds_ago // 86400)
    return "ontem" if days == 1 else f"{days} dias"
